content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体",
            "criterion": "核查签约主体的合法存续性与履约适格性",
            "check_points": [
                "通过权威工商数据库（如国家企业信用信息公示系统）核查该主体是否存在未结案的重大诉讼、仲裁、失信被执行、严重违法失信等涉法涉诉记录",
                "核对营业执照所载经营范围，确认合同项下标的（尤其服务内容或产品类型）明确属于其登记的经营范围内",
                "逐项比对合同中列明的主体信息（联系地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "如合同涉及软件、技术系统等采购，须核查卖方是否拥有该软件的核心知识产权（如著作权登记证书、源代码权属声明、授权链条完整性），或已获得合法有效的再许可权"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架—完整性审查",
            "criterion": "确保合同核心条款结构完整、要素齐备、逻辑闭环",
            "check_points": [
                "检查是否完整涵盖以下必备条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用限制、产品质量/服务标准及保证、交付方式与地点、验收标准与流程、完成时限（含里程碑）、违约责任（含违约金计算方式与上限）、司法管辖法院/仲裁机构、不可抗力定义与后果、廉洁承诺条款、合同变更程序、合同份数及效力、电子送达约定（含有效邮箱/短信接收方式）",
                "确认合同中是否明确指定主要项目负责人，并完整载明其姓名、身份证号码（脱敏处理后可留末四位）、联系电话及职责权限",
                "核查采购内容是否具体化：品种、规格、型号、等级、花色等须清晰列明；若存在复杂技术参数或定制化要求，应通过附件形式固化并注明‘附件为本合同不可分割组成部分’",
                "核验合同金额表述：数量单位明确、单价与总价分列、币种标注（如人民币/USD）、大小写一致；总价须与各分项合计严格吻合；禁止出现‘暂定’‘约’‘左右’等模糊表述",
                "审查付款计划：是否设置与履约节点挂钩的分期付款条件（如预付款、到货款、初验款、终验款、质保金）；质保金比例合理（通常5%-10%），且明确约定于免费维保期届满后X个工作日内无息支付；每期付款均须注明对应发票类型（增值税专用/普通发票）及开票时限"
            ]
        },
        {
            "id": "C3",
            "section": "合同框架—期限与计时规范",
            "criterion": "确保合同期限及时间节点定义严谨、无歧义",
            "check_points": [
                "合同期限须以明确起止日期（YYYY-MM-DD格式）或可精确推算的起止时点（如‘自双方签字盖章之日起满12个月’）予以界定",
                "所有时间单位须明确定义：‘日’指自然日还是工作日；‘季度’指自然季度（1-3月、4-6月等）还是滚动季度（自起始日起每满3个月为一个季度）；避免使用‘月底’‘季末’‘及时’等模糊表述",
                "关键时限（如交付期、验收期、响应期、维保期）均需量化为具体天数，并注明计时起点（如‘自合同生效之日起’‘自货物到达现场签收次日起’）"
            ]
        },
        {
            "id": "C4",
            "section": "其他基本问题",
            "criterion": "开展文本合规性与形式一致性校验",
            "check_points": [
                "全文通读排查错别字、标点误用、标题层级混乱（如‘第一章’后直接跳至‘第三条’）、段落编号断裂等基础文本错误",
                "逐项比对合同正文与所有附件（技术协议、服务清单、报价明细等）中相同条款（如付款条件、验收标准、违约责任）的表述是否完全一致，存在差异时须以正文为准或签署补充说明",
                "清除招标文件、谈判纪要、询价函等前期流程中残留的非合同用语（如‘投标人’‘响应人’‘贵方’‘我方’），统一替换为‘甲方’‘乙方’或具体主体名称",
                "核查合同首部‘甲方/乙方’全称、签约页签章处主体名称、落款盖章名称三者是否完全一致（包括括号格式、‘有限公司’与‘有限责任公司’等法定后缀），杜绝简称、缩写或错字",
                "检索合同中援引的法律法规（如《民法典》第XXX条、《数据安全法》第X条），确认其现行有效且条款序号准确；禁止引用已废止、修订或尚未施行的法律条文",
                "确认合同正文末尾（签署栏上方）是否规范标注‘以下为合同签署栏’或‘以下无正文’字样，防止签署页被篡改或添加未授权内容"
            ]
        }
    ]
}
